CREATE TRIGGER dbo.tr_RMSTMP_InventoryMovement
ON InventoryTransferLog 
AFTER INSERT
AS

DECLARE @Date datetime,
	@ItemID Int,
	@ItemLookupCode nvarchar(25),
	@Qty Float, 
	@StoreID Int

SELECT @Date = DateTransferred,
       @ItemID = ItemID,	
       @Qty = Quantity,
       @StoreID = StoreID
FROM Inserted


SELECT @ItemLookupCode = ItemLookupCode
FROM Item
WHERE [ID] = @ItemID


INSERT INTO RMSTMP_InventoryMovement
(   --ItemID,
    ItemLookupCode,
    Quantity,
    StoreID,
    DateCreated )
VALUES ( --@ItemID,
 	 @ItemLookupCode,
         @Qty,
         @StoreID,
         @Date )

SET NOCOUNT ON
